import{_ as e,o,c as a,ai as d}from"./chunks/framework.BBSijY9B.js";const g=JSON.parse('{"title":"CleanYourTV：让 Claude Code 通过 ADB 清掉安卓电视的广告","description":"GitHub 1.4 万星项目。电视开 USB 调试，把 PROMPT.md 交给 Claude Code，它先备份，再停用广告和遥测、换上简洁桌面，一行命令就能还原。附不支持的机型和常见报错的解决办法。","frontmatter":{"title":"CleanYourTV：让 Claude Code 通过 ADB 清掉安卓电视的广告","description":"GitHub 1.4 万星项目。电视开 USB 调试，把 PROMPT.md 交给 Claude Code，它先备份，再停用广告和遥测、换上简洁桌面，一行命令就能还原。附不支持的机型和常见报错的解决办法。","tags":["GitHub 高星项目","Claude Code","ADB","Android TV","去广告"],"related":["/basics/local-computer","/basics/safety-approvals"],"sources":[{"url":"https://github.com/Gathin23/cleanyourtv","title":"Gathin23/cleanyourtv（GitHub 仓库）"},{"url":"https://github.com/Gathin23/cleanyourtv/blob/main/README.zh-CN.md","title":"CleanYourTV 中文使用指南（README.zh-CN.md）"},{"url":"https://github.com/Gathin23/cleanyourtv/blob/main/PROMPT.md","title":"PROMPT.md：交给编程助手的操作提示词"},{"url":"https://github.com/Gathin23/cleanyourtv/blob/main/docs/TROUBLESHOOTING.md","title":"docs/TROUBLESHOOTING.md：故障排查"},{"url":"https://github.com/Gathin23/cleanyourtv/blob/main/LICENSE","title":"LICENSE（MIT，字体为 SIL OFL 1.1）"}],"wordCount":4260,"readingTime":12,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"CleanYourTV：让 Claude Code 通过 ADB 清掉安卓电视的广告 | WANGXXXL"}],["meta",{"property":"og:description","content":"GitHub 1.4 万星项目。电视开 USB 调试，把 PROMPT.md 交给 Claude Code，它先备份，再停用广告和遥测、换上简洁桌面，一行命令就能还原。附不支持的机型和常见报错的解决办法。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/cases/cleanyourtv"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/cases-cleanyourtv-317094432a.png"}],["meta",{"property":"og:image:alt","content":"CleanYourTV：让 Claude Code 通过 ADB 清掉安卓电视的广告 · WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"CleanYourTV：让 Claude Code 通过 ADB 清掉安卓电视的广告 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"GitHub 1.4 万星项目。电视开 USB 调试，把 PROMPT.md 交给 Claude Code，它先备份，再停用广告和遥测、换上简洁桌面，一行命令就能还原。附不支持的机型和常见报错的解决办法。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/cases-cleanyourtv-317094432a.png"}],["meta",{"name":"twitter:image:alt","content":"CleanYourTV：让 Claude Code 通过 ADB 清掉安卓电视的广告 · WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/cases/cleanyourtv"}]]},"headers":[],"relativePath":"cases/cleanyourtv.md","filePath":"cases/cleanyourtv.md","lastUpdated":1792571830000}'),r={name:"cases/cleanyourtv.md"};function n(s,t,i,l,c,p){return o(),a("div",null,[...t[0]||(t[0]=[d(`<h1 id="cleanyourtv-让-claude-code-通过-adb-清掉安卓电视的广告" tabindex="-1">CleanYourTV：让 Claude Code 通过 ADB 清掉安卓电视的广告 <a class="header-anchor" href="#cleanyourtv-让-claude-code-通过-adb-清掉安卓电视的广告" aria-label="Permalink to &quot;CleanYourTV：让 Claude Code 通过 ADB 清掉安卓电视的广告&quot;">​</a></h1><blockquote><p><strong>说明</strong>：我们手上没有安卓电视，<strong>没有实机跑过</strong>。下面每一步都按 <a href="https://github.com/Gathin23/cleanyourtv" target="_blank" rel="noopener noreferrer">Gathin23/cleanyourtv</a> 仓库的 README、<a href="https://github.com/Gathin23/cleanyourtv/blob/main/PROMPT.md" target="_blank" rel="noopener noreferrer">PROMPT.md</a>、<a href="https://github.com/Gathin23/cleanyourtv/blob/main/docs/TROUBLESHOOTING.md" target="_blank" rel="noopener noreferrer">故障排查文档</a>和 Issues 整理，内容以 2026-10-21 仓库 main 分支为准。项目更新很快，动手前请再对照一下原仓库。</p></blockquote><h2 id="它能做什么-适合谁" tabindex="-1">它能做什么，适合谁 <a class="header-anchor" href="#它能做什么-适合谁" aria-label="Permalink to &quot;它能做什么，适合谁&quot;">​</a></h2><p>作者做这个项目的起因是：父母家的电视在打开 Netflix 之前，首页先推一条赞助广告。CleanYourTV 要解决的就是这类首页广告、推荐位和厂商预装。</p><p>它的做法是：电脑和电视连同一个 Wi-Fi，通过 ADB（安卓调试桥）连上电视，让 Claude Code 这类能跑终端命令的编程助手照着仓库里的 <code>PROMPT.md</code> 一步步操作：</p><ol><li><strong>先备份</strong>：保存已安装应用列表和相关设置。</li><li><strong>停用</strong>厂商的遥测、广告服务、推荐内容和不需要的预装应用，用的是 <code>pm disable-user</code>。<strong>只停用，不卸载</strong>，所以能还原。</li><li><strong>装一个简洁桌面</strong>（包名 <code>com.gathin.tvhome</code>，约 405 KB），设成默认主页：纯黑背景，底部一排常用应用，风格接近 Apple TV。</li></ol><p>仓库原话是：<strong>不需要 root、不刷机、不用数据线、什么都不卸载，改主意了一行命令还原。</strong> 作者说，把这个仓库给助手当参考，整个过程大约 15 分钟。</p><p><strong>适合</strong>：家里有安卓电视、Google TV 或电视盒子，被开机广告和推荐位烦到的人；也适合想看看「把真实设备交给 AI 编程助手操作」是什么样的人。</p><p><strong>不适合</strong>：不想碰开发者选项、不想在电脑上开终端的人。整个过程要你在电视上点授权、回答几道选择题，不是一键完成。</p><p>截至 2026-10-21，仓库约 <strong>1.44 万</strong> Star，README 写的是已记录 147 款电视、49 个品牌。</p><h2 id="哪些电视能用-哪些不能" tabindex="-1">哪些电视能用，哪些不能 <a class="header-anchor" href="#哪些电视能用-哪些不能" aria-label="Permalink to &quot;哪些电视能用，哪些不能&quot;">​</a></h2><table tabindex="0"><thead><tr><th>情况</th><th>说明</th></tr></thead><tbody><tr><td>✅ Android TV / Google TV</td><td>小米、TCL、海信、索尼、一加、realme、Nvidia Shield 等大多数机型都能用（<code>PROMPT.md</code> 原文列举）。仓库 <code>examples/</code> 里按型号收了停用清单，TCL、索尼、小米最多。</td></tr><tr><td>⚠️ 新桌面有系统版本要求</td><td>桌面 APK 要求 <strong>Android 8.0（API 26）及以上</strong>。有些设备的清理清单在，但系统版本太低，桌面装不上。</td></tr><tr><td>❌ 三星（Tizen）</td><td>不支持。仓库记录了一台 2021 款 Tizen 电视：局域网里没有 ADB，没法停用应用。</td></tr><tr><td>❌ LG（webOS）</td><td>不支持本项目的安卓桌面。社区有 webOS 方向的衍生项目，登记在 <a href="https://github.com/Gathin23/cleanyourtv/blob/main/SHOWCASE.md" target="_blank" rel="noopener noreferrer">SHOWCASE.md</a>，不属于本项目本身。</td></tr><tr><td>❌ Fire TV</td><td><code>PROMPT.md</code> 写明不适用于 Fire TV，Fire OS 也限制替换默认桌面。仓库里有几份 Fire TV 的停用清单，只能参考着手动处理。</td></tr><tr><td>⚠️ 部分国行电视</td><td>有的会拒绝安装任何外部 APK（报 <code>INSTALL_FAILED_VERIFICATION_FAILURE</code>），有的不允许第三方桌面当主页。这类电视只能做「停用广告」这一半，换桌面做不了。不能只凭品牌判断，要看具体型号。</td></tr><tr><td>⚠️ 运营商定制盒子</td><td>有的运营商固件把 USB 调试和无线调试开关都去掉或锁成灰色，这样就完全连不上，本项目无从下手。</td></tr></tbody></table><p>不在清单里的型号也可以试：<code>PROMPT.md</code> 会让助手在你的真实设备上自己排查。动手前先在<a href="https://github.com/Gathin23/cleanyourtv/blob/main/examples/README.md" target="_blank" rel="noopener noreferrer">机型清单</a>里搜一下自己的型号，看对应目录的说明。</p><h2 id="安装-准备工作" tabindex="-1">安装：准备工作 <a class="header-anchor" href="#安装-准备工作" aria-label="Permalink to &quot;安装：准备工作&quot;">​</a></h2><div class="steps"><ol><li><p><strong>电视上打开 USB 调试</strong>：进入「设置 → 设备偏好设置 → 关于」，在「版本号 / Build」上连按 <strong>7 次</strong>确定键，返回后进「开发者选项」，打开 <strong>USB 调试</strong>。如果还有「网络调试」或「ADB 调试」开关，也一起打开。菜单名称因机型而异。电视保持开机。</p></li><li><p><strong>电脑和电视连同一个 Wi-Fi</strong>：助手要在局域网里找到电视，默认走 ADB 的 5555 端口。也可以在电视的网络设置里查到 IP，直接告诉助手。</p></li><li><p><strong>电脑上准备工具</strong>：</p><ul><li><strong>编程助手</strong>：仓库推荐 <a href="https://claude.com/product/claude-code" target="_blank" rel="noopener noreferrer">Claude Code</a>，也说 <a href="https://github.com/openai/codex" target="_blank" rel="noopener noreferrer">Codex</a>、<a href="https://github.com/google-gemini/gemini-cli" target="_blank" rel="noopener noreferrer">Gemini CLI</a> 能用。按官方说明安装并登录即可。</li><li><strong>Python 3</strong>：仓库自带的 <code>tools/tv.py</code> 是纯 Python 写的 ADB 客户端，系统自带的 <code>adb</code> 被拦住时可以用它。</li><li><strong>adb（可选）</strong>：电视只支持「无线调试」配对时，要用官方 <code>adb</code> 执行 <code>adb pair</code> 一次。</li><li><strong>编译桌面的环境</strong>：JDK 17、Android SDK Platform 34、Build Tools 34.0.0。macOS 可以用 <code>brew install openjdk@17 android-commandlinetools</code>，再运行 <code>sdkmanager &quot;platforms;android-34&quot; &quot;build-tools;34.0.0&quot;</code>。Windows 装好 Android Studio 即可。</li></ul></li><li><p><strong>克隆仓库</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/Gathin23/cleanyourtv.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cleanyourtv</span></span></code></pre></div><p>仓库<strong>不提供现成的 APK</strong>，桌面由安装脚本现场编译，作者说大约一分钟。</p></li></ol></div><div class="warning custom-block"><p class="custom-block-title">先看一眼电视的 USB 口</p><p>有些盒子（例如小米盒子 S）开着 USB 调试时会切断 USB 口的供电，插在上面的 USB 音箱或 U 盘会没反应。做完把 USB 调试关掉就好，新桌面不需要它。</p></div><h2 id="使用-把-prompt-md-交给-claude-code" tabindex="-1">使用：把 PROMPT.md 交给 Claude Code <a class="header-anchor" href="#使用-把-prompt-md-交给-claude-code" aria-label="Permalink to &quot;使用：把 PROMPT.md 交给 Claude Code&quot;">​</a></h2><div class="steps"><ol><li><strong>在仓库目录里启动 Claude Code</strong>，把 <a href="https://github.com/Gathin23/cleanyourtv/blob/main/PROMPT.md" target="_blank" rel="noopener noreferrer"><code>PROMPT.md</code></a> 两条分隔线之间的那段英文提示词贴进去，把 <code>&lt;MODEL NAME HERE&gt;</code> 换成你的电视型号。</li><li><strong>告诉它你已经克隆了仓库</strong>。<code>PROMPT.md</code> 特别提到：这样助手会直接复用 <code>tools/</code> 和 <code>launcher/</code>，不用从头写，只需要改 <code>launcher/.../values/config.xml</code>。</li><li><strong>在电视上点「允许 USB 调试」</strong>：助手连接时，电视会弹出「Allow USB debugging?」，用遥控器点允许。</li><li><strong>回答三四道选择题</strong>：你平时用哪些应用、底部放哪四个、要不要保留语音助手、Chromecast 投屏和系统更新。没勾的才会被停用。</li><li><strong>跟着它检查</strong>：每改一步，助手会从电视截图回来确认。最后它会交给你还原脚本、编译安装脚本，以及一份说明（怎么重新启用某个应用、怎么换快捷栏顺序和壁纸）。</li></ol></div><p>可以这样跟 Claude Code 说（下面是我们写的示例，正式提示词以 <code>PROMPT.md</code> 原文为准）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我已经在当前目录克隆了 cleanyourtv 仓库，请复用 tools/ 和 launcher/。</span></span>
<span class="line"><span>按照 PROMPT.md 的流程处理我的电视，型号是：&lt;你的电视型号&gt;。</span></span>
<span class="line"><span>要求：</span></span>
<span class="line"><span>1. 改动之前先完整备份，并生成还原脚本，告诉我放在哪；</span></span>
<span class="line"><span>2. 每批只停用少量应用，每批之后截图确认；</span></span>
<span class="line"><span>3. 碰到流媒体应用、语音助手、投屏、系统更新，先列清单问我；</span></span>
<span class="line"><span>4. 做完帮我关闭网络 ADB，并用 tools/adb-closed.py 确认端口已关闭。</span></span></code></pre></div><h3 id="prompt-md-里的几条硬规矩" tabindex="-1">PROMPT.md 里的几条硬规矩 <a class="header-anchor" href="#prompt-md-里的几条硬规矩" aria-label="Permalink to &quot;PROMPT.md 里的几条硬规矩&quot;">​</a></h3><p>这些写在提示词里，助手会照做。你也要知道，方便盯着它：</p><ul><li><strong>系统应用只停用，不卸载</strong>（<code>pm disable-user --user 0</code>）。</li><li><strong>这些不能停</strong>：负责播放 HDMI 和电视信号的应用、输入源菜单、遥控器和蓝牙配对、屏幕键盘、Google Play 商店和 Play 服务。</li><li><strong>分小批停用</strong>，每批之后截图，否则出了问题不知道是哪一个导致的。</li><li><strong><code>pm</code> 命令一次只执行一条</strong>，连在一起写可能执行完第一条就悄悄停了。</li><li><strong>名字里带 factory、production、fac menu 的工厂菜单包，一律不要打开</strong>，只看不开也不行（见下面踩坑部分）。</li></ul><h2 id="备份和一行还原" tabindex="-1">备份和一行还原 <a class="header-anchor" href="#备份和一行还原" aria-label="Permalink to &quot;备份和一行还原&quot;">​</a></h2><h3 id="用-prompt-md-时" tabindex="-1">用 PROMPT.md 时 <a class="header-anchor" href="#用-prompt-md-时" aria-label="Permalink to &quot;用 PROMPT.md 时&quot;">​</a></h3><p>助手在改动前会把完整的应用列表、已停用列表、<code>getprop</code> 输出和全部设置保存到备份目录，并写好一个能重新启用所有被停用应用的还原脚本。<strong>备份目录和还原脚本的位置一定要让它告诉你</strong>，自己记下来。</p><h3 id="手动用仓库脚本时" tabindex="-1">手动用仓库脚本时 <a class="header-anchor" href="#手动用仓库脚本时" aria-label="Permalink to &quot;手动用仓库脚本时&quot;">​</a></h3><p><code>tools/disable.sh</code> 停用之前会先记录：清单里每个应用原来是启用、已停用还是没安装，当时的默认主页，还有三项动画缩放设置。记录保存在电脑的 <code>~/.cleanyourtv/</code>，每台电视、每份清单各一份；同一份清单重复运行不会覆盖最初的记录。注意它<strong>不会</strong>保存完整应用列表和全部系统设置，需要完整快照的话要另外先存。</p><p><strong>一行还原</strong>（把 IP 和清单路径换成你实际用过的）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Android TV</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TV_HOST</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">192.168.1.50</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tools/restore.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">你的机</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">型</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/debloat.txt</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Google TV：最后加上原桌面的备用包名</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TV_HOST</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">192.168.1.50</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tools/restore.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">你的机</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">型</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/debloat.txt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.google.android.apps.tv.launcherx</span></span></code></pre></div><p>几点要知道：</p><ul><li>有记录时，会把主页还给当初真正占着它的那个桌面；你自己原本就停用的应用，还原后仍是停用。</li><li>找不到记录时，脚本会提示你，然后把清单里的应用全部启用、动画缩放恢复成 <code>1.0</code>。这和精确还原不完全一样。</li><li>还原<strong>不会卸载</strong> CleanYourTV 桌面，想删的话到电视「设置 → 应用」里卸载。</li><li>电脑连不上电视时，也可以直接在电视「设置 → 应用」里把被停用的应用重新启用。</li><li>Windows 用 <code>tools/disable.ps1</code> 和 <code>tools/restore.ps1</code>。</li></ul><h3 id="做完一定要关掉调试" tabindex="-1">做完一定要关掉调试 <a class="header-anchor" href="#做完一定要关掉调试" aria-label="Permalink to &quot;做完一定要关掉调试&quot;">​</a></h3><p>ADB 的 5555 端口是<strong>明文</strong>连接，有的固件（<code>ro.adb.secure=0</code>）甚至不需要授权，同一局域网的任何设备都能拿到命令行。仓库要求做完之后：</p><ol><li>在电视的开发者选项里关闭 USB 调试和网络 / ADB 调试，并撤销 USB 调试授权。</li><li>重启电视，在电脑上运行 <code>python3 tools/adb-closed.py &lt;电视IP&gt;</code>，确认端口已关闭。</li></ol><p>用 <code>nc</code> 检查时，只有 <code>Connection refused</code> 才算关了。macOS 会拦 <code>nc</code>，报的 <code>No route to host</code> 证明不了任何事。</p><p>新桌面在关闭调试后照常工作。</p><h2 id="踩坑与解决" tabindex="-1">踩坑与解决 <a class="header-anchor" href="#踩坑与解决" aria-label="Permalink to &quot;踩坑与解决&quot;">​</a></h2><p>以下全部来自仓库的 <a href="https://github.com/Gathin23/cleanyourtv/blob/main/docs/TROUBLESHOOTING.md" target="_blank" rel="noopener noreferrer">TROUBLESHOOTING.md</a>、README 和相关 Issues。</p><h3 id="连接类" tabindex="-1">连接类 <a class="header-anchor" href="#连接类" aria-label="Permalink to &quot;连接类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>现象</th><th>原因和解决办法</th></tr></thead><tbody><tr><td>macOS 上 <code>adb connect</code> 报 <code>No route to host</code>，但端口明明是开的</td><td>macOS 的「本地网络」隐私权限把官方 <code>adb</code> 拦了。别在这上面耗时间，改用仓库的 <code>tools/venv/bin/python -I tools/tv.py</code>（纯 Python 客户端，不依赖 <code>adb</code> 程序）。</td></tr><tr><td>电视上反复弹「Allow USB debugging?」，可 <code>adb devices</code> 已经能用</td><td>用了一把电视还没认可的密钥。<code>tv.py</code> 现在会复用 <code>~/.android/adbkey</code>。每次用未授权的密钥连接，电视上就多排队一个弹窗，先按返回键把弹窗全部关掉，再继续。</td></tr><tr><td>开了 USB 调试，5555 端口一直打不开（部分 Google TV，如 Skyworth 代工的飞利浦）</td><td>用官方 <code>adb</code> 走一次「无线调试」配对：<code>adb pair &lt;ip&gt;:&lt;端口&gt; &lt;配对码&gt;</code>，再 <code>adb connect</code>，然后 <code>adb tcpip 5555</code>，之后 <code>tools/tv.py</code> 就能用了。<code>adb tcpip</code> 打开的 5555 一般重启后就失效；Wi-Fi 断开时安卓也会自动关掉无线调试。</td></tr><tr><td>找不到「无线调试」开关（小米等）</td><td>正常现象。这些机型只开 USB 调试，就会在 5555 端口打开网络 ADB。</td></tr><tr><td>开发者选项被隐藏，或点版本号要密码（运营商盒子）</td><td>往往只是入口被锁。可以从 Play 商店装一个能按名称打开界面的应用（如 Activity Launcher），打开 <code>com.android.tv.settings/.system.development.DevelopmentActivity</code>，在那里打开 USB 调试。</td></tr><tr><td>USB 调试是灰色的，也没有无线调试，连接一直超时（<a href="https://github.com/Gathin23/cleanyourtv/issues/227" target="_blank" rel="noopener noreferrer">#227</a>，Airtel 盒子）</td><td>运营商固件去掉了开关，这时超时是固件问题，不是 Wi-Fi、路由器或网线的问题，别去折腾网络。没有这两个开关，本项目就无从下手。</td></tr><tr><td>电视在单独的 VLAN / IoT 网络里，调试开着但 <code>tv.py</code> 超时</td><td>路由器挡住了电脑访问电视。临时加一条只放行「电脑 → 电视 TCP 5555」的防火墙规则，关闭 ADB 后删掉。不要把整个网段放开。</td></tr><tr><td>Windows 上第一条批处理命令变成乱码</td><td>PowerShell 5.1 会在管道文本前加 BOM。<code>tv.py</code> 已经处理了，<code>.ps1</code> 脚本也改成了干净的 UTF-8。</td></tr><tr><td>Git Bash 把 <code>/data/local/tmp</code> 改成了 Windows 路径</td><td>脚本已经设置了 <code>MSYS_NO_PATHCONV=1</code>。编译前记得设置 <code>JAVA_HOME</code> 和 <code>ANDROID_HOME</code>。</td></tr></tbody></table><h3 id="安装和使用类" tabindex="-1">安装和使用类 <a class="header-anchor" href="#安装和使用类" aria-label="Permalink to &quot;安装和使用类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>现象</th><th>原因和解决办法</th></tr></thead><tbody><tr><td>装 APK 报 <code>INSTALL_FAILED_VERIFICATION_FAILURE</code>，连厂商自己的 APK 也装不上</td><td>部分国行电视拒绝一切外部安装。只做停用广告这一半，换桌面这一半在这台电视上做不了，别反复重试。</td></tr><tr><td>Play 保护机制拦截桌面，提示「为旧版安卓构建」</td><td>旧版代码的目标 SDK 是 29，现在已是 34。如果你用的是旧版代码，拉取最新代码重新编译。</td></tr><tr><td>Android 14 上 <code>adb install</code> 卡住不动</td><td>它在等电视屏幕上的确认。改为先把 APK 推到电视上，再在 shell 里执行 <code>pm install -r</code>。</td></tr><tr><td>推送大文件时卡住</td><td>用 <code>tools/b64push.py</code>，它把 APK 拆成 base64 分块上传，并核对校验值。</td></tr><tr><td>Google TV 停用原桌面后，主页被设置向导抢走，甚至系统反复崩溃、Wi-Fi 每分钟断一次</td><td>罪魁是 <code>com.google.android.tungsten.setupwraith</code>。已经卡住的话，先执行 <code>tools/tv.py &#39;pm enable --user 0 com.google.android.apps.tv.launcherx&#39;</code> 把原桌面救回来。</td></tr><tr><td>停用 setupwraith 后电视直接掉线，重启也连不上 Wi-Fi</td><td>首次开机时保存的 Wi-Fi 属于 setupwraith，停用它，安卓就会把这个网络删掉。停用前先运行 <code>tools/tv.py &quot;dumpsys wifi&quot; | grep -o &#39;cname=[^ ]*&#39;</code> 检查；如果显示 setupwraith，先在设置里「忘记」这个 Wi-Fi 再重新连上。<code>tools/disable.sh</code> 在这种情况下会自动跳过它。已经掉线的话，用遥控器或 USB 键盘在电视上重新连 Wi-Fi。</td></tr><tr><td>Google 自家 Chromecast / Google TV Streamer 停用 setupwraith 后，手机投屏提示 Untrusted device</td><td>投屏凭据存在 setupwraith 里。要么不停用它（和原桌面），要么每次开机后先启用它、等凭据加载好再停用，详见故障排查文档。</td></tr><tr><td>换桌面后主页还是原来的，或按主页键进了工厂测试程序</td><td>一定要等新桌面装好、能正常运行，再停用原桌面；安装脚本已经按这个顺序执行。<code>set-home-activity</code> 显示 <code>Success</code> 不代表真的切换了，要用 <code>dumpsys activity activities | grep mFocusedApp</code> 确认。</td></tr><tr><td>国行小米电视（MiTV-AETP0 等）设置默认主页显示成功，但实际不生效</td><td>系统按包名白名单过滤第三方主页。仓库的<a href="https://github.com/Gathin23/cleanyourtv/blob/main/docs/devices/xiaomi-mitv-aetp0-dofus.md" target="_blank" rel="noopener noreferrer">设备说明</a>里有可选的处理和回滚步骤。</td></tr><tr><td>打开工厂菜单后，输入源按键失灵、CEC 关闭，重启后 Play 服务、Netflix、投屏被禁用（<a href="https://github.com/Gathin23/cleanyourtv/issues/470" target="_blank" rel="noopener noreferrer">#470</a>，海尔 / CVTE 板）</td><td>只是「看看这个包是干什么的」就会触发。要用 <code>dumpsys package &lt;包名&gt;</code> 看，不要启动它。已经触发了，按故障排查文档的步骤退出工厂模式，再重新打开 CEC。</td></tr><tr><td>切换桌面后没有屏幕键盘（小米）</td><td>默认输入法指向了一个没安装的百度键盘。执行 <code>tools/tv.py &#39;ime set com.google.android.inputmethod.latin/com.android.inputmethod.latin.LatinIME&#39;</code>。</td></tr><tr><td>播放直播电视、HDMI 或 Netflix 时，截图是空的（<a href="https://github.com/Gathin23/cleanyourtv/issues/92" target="_blank" rel="noopener noreferrer">#92</a>）</td><td>电视本身的限制，不代表连接或播放有问题。截图前先按主页键。</td></tr><tr><td>部分联发科电视（小米等）上截图得到坏的 PNG</td><td>截图前面混进了一行日志。先在电视上 <code>screencap -p /data/local/tmp/s.png</code>，再把文件拉回电脑。</td></tr><tr><td>重启后有些应用又被启用了（如 TCL Android 9 的用户中心）</td><td>部分固件每次开机都会按自己的清单重新启用。在清单开头注明即可，不用每次重启后再停用一遍。</td></tr><tr><td>停用后收不到系统更新</td><td>多数清单会停用系统更新服务，需要更新时重新启用它。流媒体应用仍然可以通过保留的 Play 商店更新。</td></tr></tbody></table><h3 id="想顺便屏蔽应用内广告" tabindex="-1">想顺便屏蔽应用内广告？ <a class="header-anchor" href="#想顺便屏蔽应用内广告" aria-label="Permalink to &quot;想顺便屏蔽应用内广告？&quot;">​</a></h3><p>README 给了一个可选办法：安卓 9 及以上，用系统的「私人 DNS」指向去广告的 DNS（例如 AdGuard DNS）。它<strong>挡不住 YouTube 广告</strong>，而且这个 DNS 服务商能看到电视的所有 DNS 查询。如果应用无法播放或提示没有网络，就改回 <code>private_dns_mode opportunistic</code>。具体命令见原 README 的常见问题部分。</p><h2 id="原项目与许可证" tabindex="-1">原项目与许可证 <a class="header-anchor" href="#原项目与许可证" aria-label="Permalink to &quot;原项目与许可证&quot;">​</a></h2><ul><li>原仓库：<a href="https://github.com/Gathin23/cleanyourtv" target="_blank" rel="noopener noreferrer">github.com/Gathin23/cleanyourtv</a>（项目网站 <a href="https://cleanyour.tv" target="_blank" rel="noopener noreferrer">cleanyour.tv</a>，仓库曾用名 tv-vibehack，旧链接仍可访问）。</li><li>中文说明：<a href="https://github.com/Gathin23/cleanyourtv/blob/main/README.zh-CN.md" target="_blank" rel="noopener noreferrer">README.zh-CN.md</a>。</li><li>许可证：GitHub 仓库页把许可证显示为「Other / NOASSERTION」。这很可能是因为 <a href="https://github.com/Gathin23/cleanyourtv/blob/main/LICENSE" target="_blank" rel="noopener noreferrer">LICENSE</a> 文件里除了 <strong>MIT 许可证</strong>正文（Copyright (c) 2026 Gathin），还附了一段字体说明：桌面用的 Outfit 字体采用 <strong>SIL Open Font License 1.1</strong>，GitHub 的自动识别认不出这种组合。项目中文 README 也写明「项目采用 MIT 许可证」。也就是说，代码按 MIT 开源，字体按 OFL 授权。</li><li>遇到问题可以去仓库的 <a href="https://github.com/Gathin23/cleanyourtv/discussions" target="_blank" rel="noopener noreferrer">Discussions</a> 讨论。如果你的机型验证通过，也可以按 <a href="https://github.com/Gathin23/cleanyourtv/blob/main/CONTRIBUTING.md" target="_blank" rel="noopener noreferrer">CONTRIBUTING.md</a> 提交清单，下一个同型号的人就能少走弯路。</li></ul><div class="tip custom-block"><p class="custom-block-title">本页的边界</p><p>本页只做整理和中文导读，不代表原作者，也不对你的电视做任何担保。停用系统组件仍有可能出问题，所以一定要先备份、分小批操作，并确认还原路径可用。</p></div>`,48)])])}const u=e(r,[["render",n]]);export{g as __pageData,u as default};
